import json,html,sys
sys.path.insert(0,'.')
from datetime import date
from rinvo.daty import kalendarz
from rinvo.raport import szkic_maila
w=json.load(open('wyniki.json'))
e=[x for x in w['elementy'] if x['id']=='E03'][0]
e={k:e[k] for k in ['id','typ','status','tytul','skrot','wlasciciel','termin','termin_opis','do_klienta','cytaty','cytaty_zweryfikowane']}
e['cytaty']=e['cytaty'][:1]
H=lambda s:html.escape(s)
cal='\n'.join(kalendarz(date(2026,10,6))[:4])
reg=['Późniejsze wypowiedzi nadpisują wcześniejsze. W opis zapisz stan końcowy po wszystkich nadpisaniach.',
'Cytaty: DOSŁOWNY fragment transkrypcji, jedna wypowiedź, bez sklejania różnych miejsc, bez parafrazy.',
'Brak terminu w rozmowie oznacza null, nigdy nie zgaduj terminu.']
mail='\n'.join(szkic_maila(w).split('\n')[:5])
ev='\n'.join(open('oddanie/02-demo/wynik-ewaluacji.txt').read().splitlines()[:6])+'\n...\nWynik: 15/15'
tr=("Kasia: Toruńska 120. Godziny bez zmian, w tygodniu dziewiąta–osiemnasta, sobota dziewiąta–czternasta.\n[...]\n"
"Marek: Dobra. Tydzień dziewiąta–dziewiętnasta, sobota dziewiąta–czternasta. Zmienię po callu.\n[...]\n"
"Kasia: Dokładnie. A, jeszcze wracając do godzin dzwonienia. Sobotę jednak zostaw do piętnastej, nie do czternastej. Od tego miesiąca salon w sobotę jest do piętnastej, zapomniałam.\n\nMarek: Czyli sobota dziewiąta–piętnasta, tydzień dziewiąta–dziewiętnasta.")
ok=e['cytaty'][0]
bad="Sobotę jednak zostaw do piętnastej. Zmienię po callu."
P={}
P['1']=("Transkrypcja","Surowy tekst spotkania, bez obróbki.",
f"<p>W jednej rozmowie ustalenie pada dwa razy. Ważne jest to późniejsze.</p><pre>{H(tr)}</pre><p class=n>Wniosek: sobota kończy się o 15, nie o 14. Liczy się ostatnia wypowiedź.</p>")
P['2']=("Ekstrakcja","claude -p dostaje transkrypcję, kalendarz dat i prompt.",
f"<p>Kalendarz pozwala zamienić „dzisiaj” czy „do piątku” na konkretną datę (spotkanie: 6.10.2026):</p><pre>{H(cal)}</pre><p>Fragment reguł z promptu:</p><ul>{''.join('<li>'+H(r)+'</li>' for r in reg)}</ul>")
P['3']=("Walidacja i cytaty","Kod sprawdza kształt danych i szuka każdego cytatu w transkrypcji.",
f"<div class=ok><b>zweryfikowany</b><pre>{H(ok)}</pre>Jest w transkrypcji znak w znak.</div><div class=bad><b>niezweryfikowany (przykład wymyślony)</b><pre>{H(bad)}</pre>To sklejka dwóch wypowiedzi z różnych miejsc. Nie występuje w tekście, więc element dostaje flagę cytaty_zweryfikowane: false i trafia do przeglądu.</div>")
P['4']=("wyniki.json","Jedno źródło prawdy: lista elementów ze statusem, właścicielem, terminem i cytatami.",
f"<p>Jeden element z prawdziwego pliku (cytaty skrócone do jednego):</p><pre>{H(json.dumps(e,ensure_ascii=False,indent=2))}</pre>")
P['5']=("raport.html","Szkice dla człowieka: karty elementów i szkic maila do klienta.",
f"<div class=card><b>{H(e['tytul'])}</b><p>{H(e['skrot'])}</p><small>właściciel: {e['wlasciciel']} · termin: {e['termin']} ({H(e['termin_opis'])}) · cytaty: zweryfikowane</small></div><p>Początek szkicu maila:</p><pre>{H(mail)}</pre>")
P['6']=("Człowiek zatwierdza","Ostatnie słowo ma człowiek. Nic nie jest wysyłane automatycznie.",
"<ul><li>Czyta kartę i sprawdza cytat obok.</li><li>Poprawia skrót, właściciela albo termin, jeśli trzeba.</li><li>Zatwierdza lub odrzuca każdy element.</li><li>Mail kopiuje i wysyła sam. Narzędzie niczego nie wysyła.</li></ul>")
P['E']=("Ewaluacja","Osobno: porównanie wyniku z oczekiwane.json, ręcznie opisanym wzorcem.",
f"<pre>{H(ev)}</pre><p class=n>Ewaluacja nie jest częścią przepływu. Sprawdza, czy zmiana promptu nie pogorszyła wyników.</p>")
order=['1','2','3','4','5','6']
btn=''.join(f'<button class=step data-k={k} aria-pressed=false><span class=num>{k}</span>{P[k][0]}</button>' for k in order)
btn+=f'<button class="step side" data-k=E aria-pressed=false><span class=num>+</span>Ewaluacja</button>'
data=json.dumps({k:{'t':v[0],'d':v[1],'h':v[2]} for k,v in P.items()},ensure_ascii=False).replace('</','<\\/')
out=f'''<!doctype html><html lang=pl><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Proces Rinvo: prototyp przepływu</title><style>
:root{{--tlo:#E9EDF1;--ark:#fff;--at:#14213D;--sz:#5B6675;--zol:#F2B705}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--tlo);color:var(--at);font:16px/1.5 "Avenir Next","Segoe UI",system-ui,sans-serif;padding:16px}}
main{{max-width:880px;margin:0 auto;background:var(--ark);border-radius:12px;padding:24px}}
h1{{font-size:1.4rem;margin:0 0 4px}}.lead{{color:var(--sz);margin:0 0 20px}}
.flow{{display:flex;flex-wrap:wrap;gap:8px;align-items:stretch}}
.step{{font:inherit;color:var(--at);background:var(--ark);border:2px solid var(--at);border-radius:10px;padding:10px 12px;cursor:pointer;display:flex;gap:8px;align-items:center;text-align:left}}
.step .num{{width:24px;height:24px;border-radius:50%;background:var(--tlo);display:grid;place-items:center;font-size:.85rem;flex:none}}
.step[aria-pressed=true]{{background:var(--zol);border-color:var(--at)}}.step[aria-pressed=true] .num{{background:var(--ark)}}
.step:not(:last-child):not(.side)::after{{content:"→";color:var(--sz);margin-left:4px}}
.side{{border-style:dashed;border-color:var(--sz);margin-left:auto}}
button:focus-visible{{outline:3px solid var(--at);outline-offset:2px}}
#p{{margin-top:20px;border-top:1px solid var(--tlo);padding-top:16px}}#p h2{{margin:0;font-size:1.15rem}}#p .d{{color:var(--sz);margin:2px 0 12px}}
pre{{background:var(--tlo);padding:12px;border-radius:8px;overflow-x:auto;white-space:pre-wrap;word-break:break-word;font:.85rem/1.5 ui-monospace,Menlo,monospace;margin:8px 0}}
.n{{color:var(--sz)}}.ok,.bad,.card{{border:1px solid var(--sz);border-radius:8px;padding:10px 12px;margin:8px 0}}.ok{{border-left:6px solid var(--at)}}.bad{{border-left:6px solid var(--sz);border-style:dashed}}
.card small{{color:var(--sz)}}li{{margin:4px 0}}
@media(max-width:560px){{main{{padding:16px}}.step{{width:100%}}.step::after{{display:none}}.side{{margin-left:0}}}}
</style></head><body><main><h1>Jak działa proces</h1><p class=lead>Kliknij krok, żeby zobaczyć prawdziwy przykład z danych Auto Tama.</p>
<nav class=flow aria-label="Kroki procesu">{btn}</nav><section id=p aria-live=polite></section></main>
<script>const D={data};const p=document.getElementById('p');
function show(k){{document.querySelectorAll('.step').forEach(b=>b.setAttribute('aria-pressed',b.dataset.k===k));
const x=D[k];p.innerHTML='<h2></h2><p class=d></p><div>'+x.h+'</div>';p.querySelector('h2').textContent=x.t;p.querySelector('.d').textContent=x.d;}}
document.querySelectorAll('.step').forEach(b=>b.onclick=()=>show(b.dataset.k));show('1');</script></body></html>'''
open('oddanie/01-prototyp-procesu/proces.html','w').write(out)
EOF
